{"description":"读取已保存的运行输入参数","command":"p=$(python3 -c 'import json; print(json.dumps({"run_ids":[i["run_id"] for i in json.load(open("submission.json"))["items"]]}))' | ELECTRON_RUN_AS_NODE=1 "$DSH_HARNESS_COMFYUI_NODE_EXECUTABLE" --expose-internals "$DSH_HARNESS_COMFYUI_CLI" --quiet generation run-inputs --stdin) || exit $?; cp "$p" run-inputs.json; python3 - <<'PY'
import json,pathlib
r=json.load(open('run-inputs.json'))['runs']; m=json.load(open('manifest.json'))['items']
for i,(x,y) in enumerate(zip(r,m),1):
 a=x.get('arguments',{}); params=a.get('parameters',{}); text=pathlib.Path(y['parameter_files']['positive_prompt']).read_text(); print(i,x.get('lookup_status'), 'prompt_equal=',params.get('positive_prompt')==text,'seed=',params.get('seed'))
PY"}

